- name: Read back the whole actually published SOURCE S before any Edge or Pages write
  id: source-producer-checkpoint-readback
  if: env.RAVRADAR_SOURCE_PRODUCER_SOURCE_ACTIVE == 'true'
  shell: bash
  env:
    SUPABASE_URL: ${{ secrets.SUPABASE_URL }}
    SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}
  run: |
    set -euo pipefail
    test "$RAVRADAR_SOURCE_PRODUCER_PHASE" = installed
    test "$RAVRADAR_SOURCE_PRODUCER_UPGRADE_OPT_IN" = false
    test "$RAVRADAR_SOURCE_NORMAL_PRODUCER" = false
    test "${{ steps.current-private-publish.outcome }}" = success
    test "${{ steps.established-native-current-origin-checkpoint-publish.outcome }}" = success
    # Reconciliation is intentionally NOT used here: local S now exists.
    # The normal fresh restore reads the whole remote JSONB payload and
    # validates its original checksums before exact local equivalence.
    node --input-type=module <<'NODE'
    import assert from 'node:assert/strict';
    import fs from 'node:fs/promises';
    import { requireSourceProducerOutput } from './scripts/lib/source-producer-successor-source.mjs';
    import { assertSourceProducerCodeOnlyCaller } from './scripts/select-source-producer-code-only-source.mjs';
    import { restoreProtectedRavScoreContinuationCheckpoint } from './scripts/protected-ravscore-continuation-checkpoint.mjs';
    try {
      requireSourceProducerOutput();
      assertSourceProducerCodeOnlyCaller(process.env);
      const result = await restoreProtectedRavScoreContinuationCheckpoint({
        targetReference:process.env.RAVRADAR_PRODUCTION_TARGET_HOUR,
      });
      assert.equal(result.reason,'protected-checkpoint-equivalent');
      assert.equal(result.restored,false);
      assert.equal(result.targetUnchanged,true);
      assertSourceProducerCodeOnlyCaller(process.env);
      console.log('SOURCE whole central S read back and equivalent to the normally saved local S; original checksums verified.');
      await fs.appendFile(process.env.GITHUB_OUTPUT,'equivalent=true\n');
    } catch {
      console.error('SOURCE_PRODUCER_S_READBACK_REFUSED');
      process.exitCode=1;
    }
    NODE

